//! Selected Lucide assets are application source, not a runtime registry.
use crate::{Error, IoSnafu, JsonSnafu, Result};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use snafu::ResultExt;
use std::{
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
    time::Duration,
};

const PINNED: &str = include_str!("../../plico/assets/lucide/SOURCE.json");
const HEADER: &str = "// @generated by plico icons; do not edit.\n";

#[derive(usage_rs::Subcommands)]
pub enum Action {
    /// Add explicitly selected icons, merging with the generated file's manifest.
    Add {
        /// Names such as lucide:save or lucide:arrow-left.
        names: Vec<String>,
        #[usage(long, default = "src/icons.rs")]
        output: PathBuf,
        /// Rust dependency exposing SvgAsset (for example plico or a renamed dependency).
        #[usage(long, default = "plico")]
        rust_crate: String,
        /// Offline source directory containing icons/*.svg and LICENSE.
        #[usage(long)]
        source: Option<PathBuf>,
    },
    /// Verify generated bytes and license offline, with no source cache required.
    Check {
        #[usage(long, default = "src/icons.rs")]
        output: PathBuf,
    },
}

#[derive(Deserialize)]
struct Catalog {
    repository: String,
    commit: String,
    license_sha256: String,
    files: BTreeMap<String, String>,
}

#[derive(Serialize, Deserialize)]
struct Selection {
    version: u32,
    provider: String,
    repository: String,
    commit: String,
    rust_crate: String,
    files: BTreeMap<String, String>,
    rust_sha256: String,
    license_sha256: String,
}

fn fail(message: impl Into<String>) -> Error {
    Error::Icons {
        message: message.into(),
    }
}
fn hash(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}
fn verify(bytes: &[u8], expected: &str, name: &str) -> Result<()> {
    if hash(bytes) != expected {
        return Err(fail(format!("{name} differs from pinned upstream bytes")));
    }
    Ok(())
}
fn sidecars(output: &Path) -> Result<(PathBuf, PathBuf)> {
    let file = output
        .file_name()
        .and_then(|s| s.to_str())
        .ok_or_else(|| fail("output requires a UTF-8 filename"))?;
    Ok((
        output.with_file_name(format!("{file}.json")),
        output.with_file_name(format!("{file}.LICENSE")),
    ))
}
fn selection(output: &Path) -> Result<Selection> {
    let (manifest, _) = sidecars(output)?;
    serde_json::from_slice(&fs::read(manifest).context(IoSnafu)?).context(JsonSnafu)
}
fn normalize(name: &str, catalog: &Catalog) -> Result<String> {
    let Some(name) = name.strip_prefix("lucide:") else {
        return Err(fail(format!("expected lucide:icon-name, got {name}")));
    };
    if name.is_empty()
        || !name.split('-').all(|part| {
            !part.is_empty()
                && part
                    .bytes()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit())
        })
    {
        return Err(fail(format!("invalid icon name: {name}")));
    }
    let file = format!("{name}.svg");
    if !catalog.files.contains_key(&file) {
        return Err(fail(format!("unknown Lucide icon: {name}")));
    }
    Ok(file)
}
fn rust_name(file: &str) -> String {
    let name = file
        .trim_end_matches(".svg")
        .replace('-', "_")
        .to_ascii_uppercase();
    if name.starts_with(|c: char| c.is_ascii_digit()) {
        format!("ICON_{name}")
    } else {
        name
    }
}
fn validate_selection(s: &Selection, catalog: &Catalog) -> Result<()> {
    if s.version != 1
        || s.provider != "lucide"
        || s.commit != catalog.commit
        || s.repository != catalog.repository
        || s.license_sha256 != catalog.license_sha256
        || s.files.is_empty()
    {
        return Err(fail(
            "selection has an unsupported version/provider or a different upstream pin",
        ));
    }
    for (name, checksum) in &s.files {
        if catalog.files.get(name) != Some(checksum) {
            return Err(fail(format!("unrecognized pinned asset: {name}")));
        }
    }
    Ok(())
}
fn read_embedded(
    output: &Path,
    s: &Selection,
    catalog: &Catalog,
) -> Result<BTreeMap<String, Vec<u8>>> {
    validate_selection(s, catalog)?;
    let rust = fs::read_to_string(output).context(IoSnafu)?;
    if !rust.starts_with(HEADER) {
        return Err(fail(
            "refusing to overwrite a file not generated by plico icons",
        ));
    }
    verify(
        rust.as_bytes(),
        &s.rust_sha256,
        "generated Rust (local edits)",
    )?;
    let mut assets = BTreeMap::new();
    for (file, checksum) in &s.files {
        let prefix = format!(
            "pub const {}: SvgAsset = SvgAsset::new(\n    r",
            rust_name(file)
        );
        let literal = rust
            .split_once(&prefix)
            .ok_or_else(|| fail(format!("missing constant for {file}")))?
            .1;
        let (hashes, rest) = literal
            .split_once('"')
            .ok_or_else(|| fail("invalid generated literal"))?;
        if hashes.is_empty() || !hashes.chars().all(|c| c == '#') {
            return Err(fail("invalid raw string delimiter"));
        }
        let ending = format!("\"{hashes}");
        let xml = rest
            .split_once(&ending)
            .ok_or_else(|| fail("unterminated generated SVG"))?
            .0;
        verify(xml.as_bytes(), checksum, file)?;
        assets.insert(file.clone(), xml.as_bytes().to_vec());
    }
    Ok(assets)
}

fn download(catalog: &Catalog, file: &str) -> Result<Vec<u8>> {
    let url = format!(
        "https://raw.githubusercontent.com/lucide-icons/lucide/{}/{file}",
        catalog.commit
    );
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(Duration::from_secs(30)))
        .build()
        .into();
    let mut response = agent
        .get(&url)
        .call()
        .map_err(|e| fail(format!("fetch {url}: {e}; use --source for offline assets")))?;
    response
        .body_mut()
        .read_to_vec()
        .map_err(|e| fail(format!("read {url}: {e}")))
}
fn load(catalog: &Catalog, source: Option<&Path>, file: &str, expected: &str) -> Result<Vec<u8>> {
    let bytes = if let Some(source) = source {
        fs::read(source.join(file)).context(IoSnafu)?
    } else {
        download(catalog, file)?
    };
    verify(&bytes, expected, file)?;
    Ok(bytes)
}
fn render(
    catalog: &Catalog,
    rust_crate: &str,
    assets: &BTreeMap<String, Vec<u8>>,
) -> Result<String> {
    let crate_path = if rust_crate == "crate" {
        "crate".to_owned()
    } else {
        format!("::{rust_crate}")
    };
    let mut out = format!(
        "{HEADER}// Lucide upstream: {}\n// License: the adjacent .rs.LICENSE file.\nuse {crate_path}::SvgAsset;\n\n",
        catalog.commit
    );
    for (file, bytes) in assets {
        let xml = std::str::from_utf8(bytes).map_err(|e| fail(format!("{file}: {e}")))?;
        let mut hashes = "#".to_owned();
        while xml.contains(&format!("\"{hashes}")) {
            hashes.push('#');
        }
        out.push_str(&format!(
            "pub const {}: SvgAsset = SvgAsset::new(\n    r{hashes}\"{xml}\"{hashes},\n);\n",
            rust_name(file)
        ));
    }
    Ok(out)
}
fn write(path: &Path, bytes: &[u8]) -> Result<()> {
    let parent = path
        .parent()
        .ok_or_else(|| fail("output needs a parent directory"))?;
    fs::create_dir_all(parent).context(IoSnafu)?;
    let mut file = tempfile::NamedTempFile::new_in(parent).context(IoSnafu)?;
    use std::io::Write;
    file.write_all(bytes).context(IoSnafu)?;
    file.persist(path)
        .map_err(|e| Error::Io { source: e.error })?;
    Ok(())
}

pub fn run(directory: &Path, command: &Action) -> Result<()> {
    let catalog: Catalog = serde_json::from_str(PINNED).context(JsonSnafu)?;
    let output = match command {
        Action::Add { output, .. } | Action::Check { output } => directory.join(output),
    };
    let (manifest, license_path) = sidecars(&output)?;
    if let Action::Check { .. } = command {
        let s = selection(&output)?;
        read_embedded(&output, &s, &catalog)?;
        verify(
            &fs::read(license_path).context(IoSnafu)?,
            &s.license_sha256,
            "LICENSE",
        )?;
        println!(
            "{} icons verified offline: {}",
            s.files.len(),
            output.display()
        );
        return Ok(());
    }
    let Action::Add {
        names,
        rust_crate,
        source,
        ..
    } = command
    else {
        unreachable!()
    };
    if names.is_empty() {
        return Err(fail("specify at least one icon, e.g. lucide:save"));
    }
    if rust_crate.is_empty()
        || !rust_crate
            .bytes()
            .enumerate()
            .all(|(i, c)| c == b'_' || c.is_ascii_alphabetic() || (i > 0 && c.is_ascii_digit()))
    {
        return Err(fail("--rust-crate must be a Rust dependency identifier"));
    }
    // Validate every requested name before network access or file mutation.
    let files: Vec<_> = names
        .iter()
        .map(|name| normalize(name, &catalog))
        .collect::<Result<_>>()?;
    let mut assets = if output.exists() {
        let s = selection(&output)?;
        if s.rust_crate != *rust_crate {
            return Err(fail("--rust-crate differs from the existing selection"));
        }
        read_embedded(&output, &s, &catalog)?
    } else if manifest.exists() || license_path.exists() {
        return Err(fail(
            "orphaned icon manifest/license; choose another output or restore the generated file",
        ));
    } else {
        BTreeMap::new()
    };
    let source = source.as_ref().map(|p| directory.join(p));
    for file in files {
        if !assets.contains_key(&file) {
            assets.insert(
                file.clone(),
                load(
                    &catalog,
                    source.as_deref(),
                    &format!("icons/{file}"),
                    &catalog.files[&file],
                )?,
            );
        }
    }
    let license = if license_path.exists() {
        let bytes = fs::read(&license_path).context(IoSnafu)?;
        verify(&bytes, &catalog.license_sha256, "LICENSE")?;
        bytes
    } else {
        load(
            &catalog,
            source.as_deref(),
            "LICENSE",
            &catalog.license_sha256,
        )?
    };
    let rust = render(&catalog, rust_crate, &assets)?;
    let s = Selection {
        version: 1,
        provider: "lucide".into(),
        repository: catalog.repository.clone(),
        commit: catalog.commit.clone(),
        rust_crate: rust_crate.clone(),
        files: assets
            .keys()
            .map(|name| (name.clone(), catalog.files[name].clone()))
            .collect(),
        rust_sha256: hash(rust.as_bytes()),
        license_sha256: catalog.license_sha256,
    };
    let mut metadata = serde_json::to_vec_pretty(&s).context(JsonSnafu)?;
    metadata.push(b'\n');
    write(&output, rust.as_bytes())?;
    write(&license_path, &license)?;
    write(&manifest, &metadata)?;
    println!(
        "{} icons generated: {}\nAdd `mod icons;` to your crate and commit the Rust, JSON and LICENSE files.",
        assets.len(),
        output.display()
    );
    Ok(())
}
